    <script>
        document.addEventListener('DOMContentLoaded', function () {

            /* =============================================
               STATE FILTER (Tours tab)
            ============================================= */
            var selectedHotelSlug = '';

            // State option click
            document.querySelectorAll('#stateOptionList li').forEach(function (li) {
                li.addEventListener('click', function () {
                    var id    = this.getAttribute('data-id');
                    var name  = this.getAttribute('data-name');

                    document.getElementById('tour-state-id').value          = id;
                    document.getElementById('tour-selected-name').textContent = name;
                    document.getElementById('tour-selected-country').textContent = 'India';
                });
            });

            // State search
            var stateSearch = document.getElementById('tourSearchInput');
            if (stateSearch) {
                stateSearch.addEventListener('input', function () {
                    var q = this.value.toLowerCase();
                    document.querySelectorAll('#stateOptionList li').forEach(function (li) {
                        var name = (li.getAttribute('data-name') || '').toLowerCase();
                        li.style.display = name.includes(q) ? '' : 'none';
                    });
                });
            }

            /* =============================================
               HOTEL FILTER (Hotels tab)
            ============================================= */

            // Hotel option click → save slug, update display
            document.querySelectorAll('#hotelOptionList li').forEach(function (li) {
                li.addEventListener('click', function () {
                    var name  = this.getAttribute('data-name');
                    var state = this.getAttribute('data-state');
                    selectedHotelSlug = this.getAttribute('data-slug');

                    document.getElementById('hotel-selected-name').textContent  = name;
                    document.getElementById('hotel-selected-state').textContent = state;
                });
            });

            // Hotel search / filter
            var hotelSearch = document.getElementById('hotelSearchInput');
            if (hotelSearch) {
                hotelSearch.addEventListener('input', function () {
                    var q = this.value.toLowerCase();
                    document.querySelectorAll('#hotelOptionList li').forEach(function (li) {
                        var name  = (li.getAttribute('data-name')  || '').toLowerCase();
                        var state = (li.getAttribute('data-state') || '').toLowerCase();
                        li.style.display = (name.includes(q) || state.includes(q)) ? '' : 'none';
                    });
                });
            }

            // Hotel SEARCH button → go to package detail page
            var hotelBtn = document.getElementById('hotelSearchBtn');
            if (hotelBtn) {
                hotelBtn.addEventListener('click', function () {
                    if (selectedHotelSlug) {
                        window.location.href = '{{ url("travel-package-detail") }}/' + selectedHotelSlug;
                    } else {
                        // No hotel selected — go to all packages
                        window.location.href = '{{ url("/travel-package") }}';
                    }
                });
            }

        });
    </script>
@endsection